NEW_FILES = {
}


def read(path):
    with io.open(path, 'r', encoding='utf-8', newline=None) as f:
        return f.read()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--root', default='.')
    ap.add_argument('--dry-run', action='store_true')
    a = ap.parse_args()
    root = os.path.abspath(a.root)
    staged, done, errors = {}, [], []
    for rel, hunks in EDITS.items():
        path = os.path.join(root, *rel.split('/'))
        if not os.path.isfile(path):
            errors.append(f'{rel}: missing')
            continue
        text = read(path)
        if GUARDS[rel] in text:
            done.append(rel)
            continue
        for k, (old, new) in enumerate(hunks, 1):
            n = text.count(old)
            if n != 1:
                errors.append(f'{rel}: edit {k}/{len(hunks)} anchor matched {n} times (need 1): '
                              f'{old.strip()[:70]!r}')
                break
            text = text.replace(old, new)
        else:
            staged[path] = text
    for rel, content in NEW_FILES.items():
        path = os.path.join(root, *rel.split('/'))
        if os.path.isfile(path):
            if read(path) == content:
                done.append(rel)
            else:
                errors.append(f'{rel}: exists with other content -- not overwritten')
            continue
        staged[path] = content
    print('=' * 78)
    print('  v33 PATCH -- no regeneration planned; the warmstart handed to Phase 0 / M5 (docs'
          ' only)')
    print('=' * 78)
    for d in done:
        print(f'  already applied: {d}')
    if errors:
        print('\n  NOTHING WRITTEN:')
        for e in errors:
            print(f'    {e}')
        return 1
    for path in staged:
        print(f'  {"would write" if a.dry_run else "writing"}: {os.path.relpath(path, root)}')
    if not staged:
        print('\n  ALREADY APPLIED. Nothing to do.')
        return 0
    if a.dry_run:
        print(f'\n  DRY RUN OK -- {len(staged)} file(s) would be written.')
        return 0
    for path, text in staged.items():
        with io.open(path, 'w', encoding='utf-8', newline='') as f:
            f.write(text)
    print(f'\n  APPLIED -- {len(staged)} file(s) written. Next: python verify_handover_v33.py --root .')
    return 0


if __name__ == '__main__':
    sys.exit(main())
